using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.ENC.Respuestas;using GraphApi.Services.ENC.Respuestas;namespace GraphApi.Controllers.ENC.Respuestas{    /// <summary>    /// Gestión de Respuestas: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("ENC/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre Respuestas")]    public class RespuestasController : Controller    {        private readonly IRespuestasService _objService;        public RespuestasController(IRespuestasService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los Respuestas, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="respuestaID">RespuestaID</param>        /// <param name="encuestaID">EncuestaID</param>        /// <param name="preguntaID">PreguntaID</param>        /// <param name="usuarioID">UsuarioID</param>        /// <param name="opcionPreguntaID">OpcionPreguntaID</param>        /// <param name="respuestaTexto">RespuestaTexto</param>        /// <param name="fechaRespuesta">FechaRespuesta</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de Respuestas</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar Respuestas",            Description = "Devuelve Respuestas aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadRespuestas>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadRespuestas>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? respuestaID,            [FromQuery] int? encuestaID,            [FromQuery] int? preguntaID,            [FromQuery] int? usuarioID,            [FromQuery] int? opcionPreguntaID,            [FromQuery] string? respuestaTexto,            [FromQuery] DateTime? fechaRespuesta,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetRespuestasDynamic(                respuestaID,                 encuestaID,                 preguntaID,                 usuarioID,                 opcionPreguntaID,                 respuestaTexto,                 fechaRespuesta,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo Respuesta.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del Respuesta a crear.</param>        /// <returns>El Respuesta recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear Respuestas",            Description = "Inserta un nuevo Respuesta en la base de datos."        )]        [ProducesResponseType(typeof(clReadRespuestas), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadRespuestas>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreateRespuestas objInput)        {            var vCreated = await _objService.CreateRespuestas(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de Respuesta.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del Respuesta.</param>        /// <returns>El Respuesta actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar Respuestas",            Description = "Actualiza uno o varios campos de Respuesta existente."        )]        [ProducesResponseType(typeof(clReadRespuestas), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadRespuestas>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdateRespuestas objInput)        {            var vUpdated = await _objService.UpdateRespuestas(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un Respuesta por su ID.        /// </summary>        [HttpDelete("{nRespuestasID:int}")]        [SwaggerOperation(            Summary = "Eliminar Respuesta",            Description = "Borra un Respuesta si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nRespuestasID)        {            var success = await _objService.DeleteRespuestas(nRespuestasID);            return success ? NoContent() : NotFound();        }    }}